mapper.select:
select distinct t.* from goods_pricing_task t
inner join goods_pricing_task_detail d on t.id = d.task_id
where t.deleted = 0

    and (t.name like concat('%',#{param.name},'%') or d.user_names like concat('%',#{param.name},'%'))


    and t.urgency = #{param.urgency}


    and t.create_time >= #{param.period.begin}


    and t.create_time < #{param.period.end}



        and d.user_ids like concat('%',#{param.userId},'%')


        and d.user_id = #{param.receiverId}

    and t.status = #{param.status}


    and ((d.user_ids like concat('%',#{param.userId},'%') and d.user_id is null) or d.user_id = #{param.receiverId})


    and ((d.user_names like concat('%',#{param.userName},'%') and d.user_id is null) or d.user_name like concat('%',#{param.userName}))

order by t.create_time desc

select t.status as code,count(id) as value from goods_pricing_task t
where t.deleted = 0

      and t.create_time >= #{param.period.begin}


      and t.create_time < #{param.period.end}

group by t.status

select sum(if(t.status = 'WAIT',1,0)) as waitNum, sum(if(td.user_id = #{param.userId} and t.status = 'EXEC',1,0)) as execNum, sum(if(td.user_id = #{param.userId} and t.status = 'OVER',1,0)) as overNum from goods_pricing_task t inner join goods_pricing_task_detail td on t.id = td.task_id where t.deleted = 0 and td.user_ids like concat('%',#{param.userId},'%')
and t.create_time >= #{param.period.begin}
and t.create_time < #{param.period.end}
